function drawJigglypuffBalloonSinger(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.2;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.05 * breathSin;
  const sX = 1.0 - 0.025 * breathSin;
  const by = -Math.abs(breathSin) * 3.0;

  // Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 42, 26 * (1.0 - 0.15 * breathSin), 6, 0, 0, Math.PI * 2); ctx.fill();

  // Chân
  ctx.fillStyle = '#e11d48';
  ctx.beginPath(); ctx.roundRect(-16, by + 28, 10, 8, 4); ctx.fill();
  ctx.beginPath(); ctx.roundRect(6,   by + 28, 10, 8, 4); ctx.fill();

  // Tai
  ctx.fillStyle = '#f472b6';
  ctx.beginPath(); ctx.moveTo(-20, by - 16); ctx.lineTo(-28, by - 36); ctx.lineTo(-12, by - 22); ctx.fill();
  ctx.beginPath(); ctx.moveTo(12,  by - 22); ctx.lineTo(28,  by - 36); ctx.lineTo(20,  by - 16); ctx.fill();
  ctx.fillStyle = '#0f172a';
  ctx.beginPath(); ctx.moveTo(-21, by - 18); ctx.lineTo(-26, by - 32); ctx.lineTo(-14, by - 22); ctx.fill();
  ctx.beginPath(); ctx.moveTo(14,  by - 22); ctx.lineTo(26,  by - 32); ctx.lineTo(21,  by - 18); ctx.fill();

  // Khối thân cầu
  ctx.fillStyle = '#f472b6';
  ctx.beginPath(); ctx.arc(0, by + 2, 22 * sX, 0, Math.PI * 2); ctx.fill();

  // Xoáy tóc
  ctx.beginPath(); ctx.arc(0, by - 17, 7, 0, Math.PI * 2); ctx.fill();

  // Mắt aqua
  if (!blink) {
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(-12, by - 2, 8, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(12,  by - 2, 8, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#06b6d4';
    ctx.beginPath(); ctx.arc(-12, by - 2, 6, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(12,  by - 2, 6, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(-14, by - 4, 3, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(-10, by,     1, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(10,  by - 4, 3, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(14,  by,     1, 0, Math.PI * 2); ctx.fill();
  }

  // Miệng
  ctx.strokeStyle = '#e11d48';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(-3, by + 10); ctx.lineTo(0, by + 12); ctx.lineTo(3, by + 10);
  ctx.stroke();

  // Tay
  ctx.fillStyle = '#f472b6';
  ctx.beginPath(); ctx.arc(-20, by + 10, 4, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(20,  by + 10, 4, 0, Math.PI * 2); ctx.fill();

  ctx.restore();
}
